ALTER TABLE "auth_events" ADD CONSTRAINT "chk_auth_events_event_type" CHECK ("event_type" IN ('LOGIN_SUCCESS', 'LOGIN_FAILED', 'ACCOUNT_LOCKED', 'LOGOUT', 'TOKEN_REFRESH', 'INSTITUTE_SWITCH', 'IMPERSONATION_START', 'IMPERSONATION_END', 'ALL_SESSIONS_REVOKED', 'PASSWORD_CHANGE', 'PASSKEY_REGISTER'));--> statement-breakpoint
ALTER TABLE "auth_events" DROP CONSTRAINT "chk_auth_events_login_portal", ADD CONSTRAINT "chk_auth_events_login_portal" CHECK ("event_type" NOT IN ('LOGIN_SUCCESS', 'LOGIN_FAILED', 'ACCOUNT_LOCKED') OR "portal" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "auth_events" DROP CONSTRAINT "chk_auth_events_login_success_scope", ADD CONSTRAINT "chk_auth_events_login_success_scope" CHECK ("event_type" <> 'LOGIN_SUCCESS' OR "scope" = "portal");--> statement-breakpoint
ALTER TABLE "auth_events" DROP CONSTRAINT "chk_auth_events_refused_attempt", ADD CONSTRAINT "chk_auth_events_refused_attempt" CHECK ("event_type" NOT IN ('LOGIN_FAILED', 'ACCOUNT_LOCKED') OR ("scope" IS NULL AND "tenant_id" IS NULL AND "reseller_id" IS NULL AND "failure_reason" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "refresh_tokens" DROP CONSTRAINT "chk_refresh_token_revoked_reason", ADD CONSTRAINT "chk_refresh_token_revoked_reason" CHECK (("revoked_at" IS NULL AND "revoked_reason" IS NULL)
        OR ("revoked_at" IS NOT NULL
          AND "revoked_reason" IS NOT NULL
          AND "revoked_reason" IN ('ROTATION', 'USER_INITIATED', 'PASSWORD_CHANGE', 'ADMIN_REVOKED')));--> statement-breakpoint
ALTER TABLE "consent_records" DROP CONSTRAINT "chk_consent_purpose", ADD CONSTRAINT "chk_consent_purpose" CHECK ("purpose" IN ('ACADEMIC_DATA_PROCESSING', 'PHOTO_VIDEO_MARKETING', 'WHATSAPP_COMMUNICATION', 'SMS_COMMUNICATION', 'AADHAAR_COLLECTION', 'BIOMETRIC_COLLECTION', 'THIRD_PARTY_EDTECH', 'BOARD_EXAM_REGISTRATION', 'TRANSPORT_TRACKING', 'HEALTH_DATA_PROCESSING', 'CCTV_MONITORING'));--> statement-breakpoint
ALTER TABLE "consent_records" DROP CONSTRAINT "chk_verification_method", ADD CONSTRAINT "chk_verification_method" CHECK ("verification_method" IS NULL OR "verification_method" IN ('DIGILOCKER_TOKEN', 'AADHAAR_OTP', 'IN_PERSON_ID_CHECK', 'SIGNED_FORM_UPLOADED', 'INSTITUTE_ERP_VERIFIED_ACCOUNT'));